def bar_backtest(bars,targets,initial_cash,half_spread=0,adverse_slip=0,fee_per_unit=0):
    # OWN schema:(time,opening_reference_cents,closing_mark_cents,open_executable_capacity).
    if type(bars) is not list or type(targets) is not list or len(bars)!=len(targets) or len(bars)>128:
        raise ValueError("invalid bar or target lists")
    if type(initial_cash) is not int or not 0<=initial_cash<=10**9:
        raise ValueError("invalid initial cash")
    if any(type(x) is not int or not 0<=x<=1000 for x in (half_spread,adverse_slip,fee_per_unit)):
        raise ValueError("invalid cost parameters")
    for index,(bar,target) in enumerate(zip(bars,targets)):
        if type(bar) is not tuple or len(bar)!=4 or any(type(x) is not int for x in bar):
            raise ValueError("invalid bar schema")
        time,opening,close,capacity=bar
        if time!=index or not 1<=opening<=10**6 or not 1<=close<=10**6 or not 0<=capacity<=10:
            raise ValueError("invalid bar domain or order")
        if opening<=half_spread+adverse_slip+fee_per_unit:
            raise ValueError("costs exceed supported sell proceeds")
        if type(target) is not int or not 0<=target<=10:raise ValueError("invalid close target")
    cash=initial_cash;position=0;pending=None;rows=[]
    for (time,opening,close,capacity),target in zip(bars,targets):
        delta=0 if pending is None else pending-position
        price=None;executed=0;unfilled=abs(delta)
        if delta>0:
            candidate=opening+half_spread+adverse_slip
            quantity=min(delta,capacity,cash//(candidate+fee_per_unit))
            if quantity:
                cash-=quantity*(candidate+fee_per_unit);position+=quantity
                executed=quantity;price=candidate
        elif delta<0:
            candidate=opening-half_spread-adverse_slip
            quantity=min(-delta,capacity,position)
            if quantity:
                cash+=quantity*(candidate-fee_per_unit);position-=quantity
                executed=-quantity;price=candidate
        unfilled-=abs(executed)
        # Opening attempt expires;mark then accept a NEW close-time target.
        equity=cash+position*close;pending=target
        rows.append((time,executed,price,cash,position,close,equity,target,unfilled))
    return tuple(rows),pending

bars=[(0,100,100,10),(1,110,115,10),(2,120,120,10)]
ledger,pending=bar_backtest(bars,[2,0,0],1000)
for row in ledger:print(row)
print("pending target",pending)
# A changed signal can first affect execution on the following bar.
print(bar_backtest(bars,[0,0,0],1000)[0][-1][6])
try:bar_backtest([(1,100,100,10)],[0],1000)
except ValueError as error:print(error)
